import{_ as t,a0 as d,w as o,s as r,ao as l,I as a,x as n,a1 as i,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Linux 中查看系統硬件製造商、型號和序列號 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中查看系統硬件製造商、型號和序列號 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中查看系統硬件製造商、型號和序列號 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中查看系統硬件製造商、型號和序列號 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180426 How To Check System Hardware Manufacturer, Model And Serial Number In Linux","title":"如何在 Linux 中查看系統硬件製造商、型號和序列號","tag":"201808","desc":""},"relativePath":"201808/20180426 How To Check System Hardware Manufacturer, Model And Serial Number In Linux.md","filePath":"[post].md"}'),u={name:"201808/20180426 How To Check System Hardware Manufacturer, Model And Serial Number In Linux.md"};function c(h,s,m,g,b,k){const e=d("Link");return o(),r("div",null,[s[27]||(s[27]=l(`<h1 id="如何在-linux-中查看系統硬件製造商、型號和序列號" tabindex="-1">如何在 Linux 中查看系統硬件製造商、型號和序列號 <a class="header-anchor" href="#如何在-linux-中查看系統硬件製造商、型號和序列號" aria-label="Permalink to “如何在 Linux 中查看系統硬件製造商、型號和序列號”">​</a></h1><p>對於 Linux 圖形界面用户和 Windows 用户來説獲取系統硬件信息都不算問題，但是對命令列用户來説想要獲取這些細節時有點兒麻煩。</p><p>甚至我們中的大多數都不知道獲取這些信息最好的命令是什麼。Linux 中有許多可用的工具集來獲取諸如製造商、型號和序列號等硬件信息。</p><p>在這裏我嘗試寫下獲取這些細節的可能的方式，你可以挑選一種最好用的。</p><p>你必須知道所有這些信息，因為當你向硬件製造商提交任何硬件問題時，你會需要它們。</p><p>這可以通過 6 種方法來實現，下面我來演示一下怎麼做。</p><h3 id="方法一-使用-dmidecode-命令" tabindex="-1">方法一：使用 dmidecode 命令 <a class="header-anchor" href="#方法一-使用-dmidecode-命令" aria-label="Permalink to “方法一：使用 dmidecode 命令”">​</a></h3><p><code>dmidecode</code> 是一個讀取電腦 DMI（<ruby>桌面管理接口<rt>Desktop Management Interface</rt></ruby>）表內容並且以人類可讀的格式顯示系統硬件信息的工具。（也有人説是讀取 SMBIOS —— <ruby>系統管理 BIOS<rt>System Management BIOS</rt></ruby>）</p><p>這個表包含系統硬件組件的説明，也包含如序列號、製造商、發佈日期以及 BIOS 修訂版本號等其它有用的信息。</p><p>DMI 表不僅描述了當前的系統構成，還可以報告可能的升級信息（比如可以支持的最快的 CPU 或者最大的內存容量）。</p><p>這將有助於分析你的硬件兼容性，比如是否支持最新版本的程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dmidecode -t system</span></span>
<span class="line"><span></span></span>
<span class="line"><span># dmidecode 2.12</span></span>
<span class="line"><span># SMBIOS entry point at 0x7e7bf000</span></span>
<span class="line"><span>SMBIOS 2.7 present.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Handle 0x0024, DMI type 1, 27 bytes</span></span>
<span class="line"><span>System Information</span></span>
<span class="line"><span> Manufacturer: IBM</span></span>
<span class="line"><span> Product Name: System x2530 M4: -[1214AC1]-</span></span>
<span class="line"><span> Version: 0B</span></span>
<span class="line"><span> Serial Number: MK2RL11</span></span>
<span class="line"><span> UUID: 762A99BF-6916-450F-80A6-B2E9E78FC9A1</span></span>
<span class="line"><span> Wake-up Type: Power Switch</span></span>
<span class="line"><span> SKU Number: Not Specified</span></span>
<span class="line"><span> Family: System X</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Handle 0x004B, DMI type 12, 5 bytes</span></span>
<span class="line"><span>System Configuration Options</span></span>
<span class="line"><span> Option 1: JP20 pin1-2: TPM PP Disable, pin2-3: TPM PP Enable</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Handle 0x004D, DMI type 32, 20 bytes</span></span>
<span class="line"><span>System Boot Information</span></span>
<span class="line"><span> Status: No errors detected</span></span></code></pre></div>`,12)),a("p",null,[s[1]||(s[1]=a("strong",null,"推薦閲讀：",-1)),s[2]||(s[2]=n()),i(e,{href:"https://www.2daygeek.com/dmidecode-get-print-display-check-linux-system-hardware-information/"},{default:p(()=>[...s[0]||(s[0]=[n("Dmidecode –– 獲取 Linux 系統硬件信息的簡單方式",-1)])]),_:1})]),s[28]||(s[28]=l(`<h3 id="方法二-使用-inxi-命令" tabindex="-1">方法二：使用 inxi 命令 <a class="header-anchor" href="#方法二-使用-inxi-命令" aria-label="Permalink to “方法二：使用 inxi 命令”">​</a></h3><p><code>inxi</code> 是 Linux 上查看硬件信息的一個靈巧的小工具，它提供了大量的選項來獲取所有硬件信息，這是我在現有的其它 Linux 工具集裏所沒見到過的。它是從 locsmif 編寫的古老的但至今看來都異常靈活的 <code>infobash</code> fork 出來的。</p><p><code>inxi</code> 是一個可以快速顯示系統硬件、CPU、驅動、Xorg、桌面、內核、GCC 版本、進程、內存使用以及大量其它有用信息的腳本，也可以用來做技術支持和調試工具。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># inxi -M</span></span>
<span class="line"><span>Machine: Device: server System: IBM product: N/A v: 0B serial: MK2RL11</span></span>
<span class="line"><span> Mobo: IBM model: 00Y8494 serial: 37M17D UEFI: IBM v: -[VVE134MUS-1.50]- date: 08/30/2013</span></span></code></pre></div>`,4)),a("p",null,[s[4]||(s[4]=a("strong",null,"推薦閲讀：",-1)),s[5]||(s[5]=n()),i(e,{href:"https://www.2daygeek.com/inxi-system-hardware-information-on-linux/"},{default:p(()=>[...s[3]||(s[3]=[n("inxi —— 一個很棒的查看 Linux 硬件信息的工具",-1)])]),_:1})]),s[29]||(s[29]=l(`<h3 id="方法三-使用-lshw-命令" tabindex="-1">方法三：使用 lshw 命令 <a class="header-anchor" href="#方法三-使用-lshw-命令" aria-label="Permalink to “方法三：使用 lshw 命令”">​</a></h3><p><code>lshw</code>（指<ruby>硬件監聽器<rt>Hardware Lister</rt></ruby>）是一個小巧靈活的工具，可以生成如內存配置、固件版本、主板配置、CPU 版本和速度、緩存配置、USB、網卡、顯卡、多媒體、打印機以及總線速度等機器中各種硬件組件的詳細報告。</p><p>它通過讀取 <code>/proc</code> 目錄下各種文件的內容和 DMI 表來生成硬件信息。</p><p><code>lshw</code> 必須以超級用户的權限運行來檢測完整的硬件信息，否則它只彙報部分信息。<code>lshw</code> 裏有一個叫做 <code>class</code> 的特殊選項，它可以以詳細的模式顯示特定的硬件信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lshw -C system</span></span>
<span class="line"><span>enal-dbo01t</span></span>
<span class="line"><span> description: Blade</span></span>
<span class="line"><span> product: System x2530 M4: -[1214AC1]-</span></span>
<span class="line"><span> vendor: IBM</span></span>
<span class="line"><span> version: 0B</span></span>
<span class="line"><span> serial: MK2RL11</span></span>
<span class="line"><span> width: 64 bits</span></span>
<span class="line"><span> capabilities: smbios-2.7 dmi-2.7 vsyscall32</span></span>
<span class="line"><span> configuration: boot=normal chassis=enclosure family=System X uuid=762A99BF-6916-450F-80A6-B2E9E78FC9A1</span></span></code></pre></div>`,5)),a("p",null,[s[7]||(s[7]=a("strong",null,"推薦閲讀：",-1)),s[8]||(s[8]=n()),i(e,{href:"https://www.2daygeek.com/lshw-find-check-system-hardware-information-details-linux/"},{default:p(()=>[...s[6]||(s[6]=[n("LSHW (Hardware Lister) –– 獲取 Linux 硬件信息的靈巧的小工具",-1)])]),_:1})]),s[30]||(s[30]=l(`<h3 id="方法四-使用-sys-文件系統" tabindex="-1">方法四：使用 /sys 文件系統 <a class="header-anchor" href="#方法四-使用-sys-文件系統" aria-label="Permalink to “方法四：使用 /sys 文件系統”">​</a></h3><p>內核在 <code>/sys</code> 目錄下的文件中公開了一些 DMI 信息。因此，我們可以通過如下方式運行 <code>grep</code> 命令來輕易地獲取機器類型。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grep &quot;&quot; /sys/class/dmi/id/[pbs]*</span></span></code></pre></div><p>或者，可以使用 <code>cat</code> 命令僅打印出特定的詳細信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /sys/class/dmi/id/board_vendor</span></span>
<span class="line"><span>IBM</span></span>
<span class="line"><span></span></span>
<span class="line"><span># cat /sys/class/dmi/id/product_name</span></span>
<span class="line"><span>System x2530 M4: -[1214AC1]-</span></span>
<span class="line"><span></span></span>
<span class="line"><span># cat /sys/class/dmi/id/product_serial</span></span>
<span class="line"><span>MK2RL11</span></span>
<span class="line"><span></span></span>
<span class="line"><span># cat /sys/class/dmi/id/bios_version</span></span>
<span class="line"><span>-[VVE134MUS-1.50]-</span></span></code></pre></div><h3 id="方法五-使用-dmesg-命令" tabindex="-1">方法五：使用 dmesg 命令 <a class="header-anchor" href="#方法五-使用-dmesg-命令" aria-label="Permalink to “方法五：使用 dmesg 命令”">​</a></h3><p><code>dmesg</code> 命令是在 Linux 上 <code>syslogd</code> 或 <code>klogd</code> 啓動前用來記錄內核消息（啓動階段的消息）的。它通過讀取內核的環形緩衝區來獲取數據。在排查問題或只是嘗試獲取系統硬件信息時，<code>dmesg</code> 非常有用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dmesg | grep -i DMI</span></span>
<span class="line"><span>DMI: System x2530 M4: -[1214AC1]-/00Y8494, BIOS -[VVE134MUS-1.50]- 08/30/2013</span></span></code></pre></div><h3 id="方法六-使用-hwinfo-命令" tabindex="-1">方法六：使用 hwinfo 命令 <a class="header-anchor" href="#方法六-使用-hwinfo-命令" aria-label="Permalink to “方法六：使用 hwinfo 命令”">​</a></h3><p><code>hwinfo</code>（<ruby>硬件信息<rt>hardware information</rt></ruby>）是另一個很棒的工具，用於檢測當前系統存的硬件，並以人類可讀的方式顯示各種硬件模組的詳細信息。</p><p>它報告關於 CPU、內存、鍵盤、鼠標、顯卡、聲卡、存儲、網絡接口、磁盤、分區、BIOS 以及橋接器等信息。它可以比其它像 <code>lshw</code>、<code>dmidecode</code> 或 <code>inxi</code> 等工具顯示更為詳細的信息。</p><p><code>hwinfo</code> 使用 libhd 庫 <code>libhd.so</code> 來收集系統上的硬件信息。該工具是為 openSuse 特別設計的，後來其它發行版也將它包含在其官方倉庫中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># hwinfo | egrep &quot;system.hardware.vendor|system.hardware.product&quot;</span></span>
<span class="line"><span> system.hardware.vendor = &#39;IBM&#39;</span></span>
<span class="line"><span> system.hardware.product = &#39;System x2530 M4: -[1214AC1]-&#39;</span></span></code></pre></div>`,13)),a("p",null,[s[10]||(s[10]=a("strong",null,"推薦閲讀：",-1)),s[11]||(s[11]=n()),i(e,{href:"https://www.2daygeek.com/hwinfo-check-display-detect-system-hardware-information-linux/"},{default:p(()=>[...s[9]||(s[9]=[n("hwinfo (Hardware Info) –– 一款靈活的檢測 Linux 系統硬件信息的工具",-1)])]),_:1})]),s[31]||(s[31]=a("hr",null,null,-1)),a("p",null,[s[13]||(s[13]=n("via: ",-1)),i(e,{href:"https://www.2daygeek.com/how-to-check-system-hardware-manufacturer-model-and-serial-number-in-linux/"},{default:p(()=>[...s[12]||(s[12]=[n("https://www.2daygeek.com/how-to-check-system-hardware-manufacturer-model-and-serial-number-in-linux/",-1)])]),_:1})]),a("p",null,[s[18]||(s[18]=n("作者：",-1)),i(e,{href:"https://www.2daygeek.com/author/vinoth/"},{default:p(()=>[...s[14]||(s[14]=[n("VINOTH KUMAR",-1)])]),_:1}),s[19]||(s[19]=n(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[15]||(s[15]=[n("lujun9972",-1)])]),_:1}),s[20]||(s[20]=n(" 譯者：",-1)),i(e,{href:"https://github.com/icecoobe"},{default:p(()=>[...s[16]||(s[16]=[n("icecoobe",-1)])]),_:1}),s[21]||(s[21]=n(" 校對：",-1)),i(e,{href:"https://github.com/pityonline"},{default:p(()=>[...s[17]||(s[17]=[n("pityonline",-1)])]),_:1})]),a("p",null,[s[24]||(s[24]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[22]||(s[22]=[n("LCTT",-1)])]),_:1}),s[25]||(s[25]=n(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[23]||(s[23]=[n("Linux中國",-1)])]),_:1}),s[26]||(s[26]=n(" 榮譽推出",-1))])])}const w=t(u,[["render",c]]);export{x as __pageData,w as default};
